package com.yonlab.offlinevoice;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;import com.k2fsa.sherpa.onnx.*;
public final class WhisperPolicyTest {
 @Test public void oneIdentitySupportsBothRegionalLists(){assertTrue(VoiceModelPolicy.compatible("KO",VoiceModelPolicy.WHISPER));assertTrue(VoiceModelPolicy.compatible("GO",VoiceModelPolicy.WHISPER));assertEquals("ALL",VoiceModelPolicy.group(VoiceModelPolicy.WHISPER));int all=0;for(VoiceModels.Entry e:VoiceModels.list(null))if(e.id.equals(VoiceModelPolicy.WHISPER))all++;assertEquals(1,all);for(String group:new String[]{"KO","GO"}){int count=0;for(VoiceModels.Entry e:VoiceModels.list(null,group))if(e.id.equals(VoiceModelPolicy.WHISPER))count++;assertEquals(1,count);}}
 @Test public void defaultsReflectDeviceTrialsAndRetiredCommunityModel(){assertEquals(VoiceModelPolicy.KO,VoiceModelPolicy.defaultId("KO"));assertEquals(VoiceModelPolicy.KO,VoiceModelPolicy.defaultId("ALL"));assertEquals(VoiceModelPolicy.EN,VoiceModelPolicy.defaultId("GO"));assertEquals(VoiceModelPolicy.WHISPER,VoiceModelPolicy.resolve("KO",null,VoiceModelPolicy.WHISPER));assertEquals(VoiceModelPolicy.WHISPER,VoiceModelPolicy.resolve("GO",null,VoiceModelPolicy.WHISPER));assertEquals(VoiceModelPolicy.KO,VoiceModelPolicy.resolve("KO",null,VoiceModelPolicy.MOON));}
 @Test public void retiredModelCannotReachRegistryOrAssetLoader()throws Exception{assertFalse(VoiceModelPolicy.known(VoiceModelPolicy.MOON));assertNull(VoiceModels.find(VoiceModelPolicy.MOON));assertEquals(new LinkedHashSet<>(Arrays.asList(VoiceModelPolicy.KO,VoiceModelPolicy.EN,VoiceModelPolicy.WHISPER,VoiceModelPolicy.WHISPER_BASE,VoiceModelPolicy.WHISPER_SMALL)),ids(VoiceModels.list(null)));for(String group:new String[]{"KO","GO"})assertEquals(new LinkedHashSet<>(Arrays.asList("KO".equals(group)?VoiceModelPolicy.KO:VoiceModelPolicy.EN,VoiceModelPolicy.WHISPER,VoiceModelPolicy.WHISPER_BASE,VoiceModelPolicy.WHISPER_SMALL)),ids(VoiceModels.list(null,group)));try{VoiceAssetStore.prepare(null,VoiceModelPolicy.MOON,()->false);fail("retired model reached an asset loader");}catch(IOException expected){assertEquals("Unknown voice model",expected.getMessage());}}
 @Test public void nativeConfigUsesAutoTranscriptionWithoutChangingWeightIdentity(){OfflineRecognizerConfig c=WhisperConfig.create(new File("whisper-test"));assertEquals("",c.getModelConfig().getWhisper().getLanguage());assertEquals("transcribe",c.getModelConfig().getWhisper().getTask());assertEquals(300,c.getModelConfig().getWhisper().getTailPaddings());assertEquals("whisper",c.getModelConfig().getModelType());assertEquals(2,c.getModelConfig().getNumThreads());assertTrue(c.getModelConfig().getWhisper().getEncoder().endsWith("tiny-encoder.int8.onnx"));assertTrue(c.getModelConfig().getWhisper().getDecoder().endsWith("tiny-decoder.int8.onnx"));assertTrue(c.getModelConfig().getTokens().endsWith("tiny-tokens.txt"));assertEquals("greedy_search",c.getDecodingMethod());}
 @Test public void newPrefixRetainsExactFileAllowlist()throws Exception{File base=Files.createTempDirectory("whisper-prefix-").toFile();byte[] value={1,2,3};Map<String,SafeModelZip.Expected> expected=new HashMap<>();expected.put("tiny-tokens.txt",new SafeModelZip.Expected(value.length,SafeModelZip.hex(MessageDigest.getInstance("SHA-256").digest(value))));File valid=archive(base,"sherpa-whisper-tiny-int8/tiny-tokens.txt",value);File unpacked=new File(base,"ok");SafeModelZip.unpack(valid,unpacked,expected,()->false,WhisperModelStore.PREFIX);assertTrue(SafeModelZip.verify(unpacked,expected,()->false));for(String path:new String[]{"sherpa-whisper-tiny-int8/../tiny-tokens.txt","sherpa-whisper-tiny-int8/unexpected.onnx","other/tiny-tokens.txt"})try{SafeModelZip.unpack(archive(base,path,value),new File(base,UUID.randomUUID().toString()),expected,()->false,WhisperModelStore.PREFIX);fail("unsafe archive entry accepted");}catch(IOException correct){} }
 @Test public void cancelAndUnknownConfiguredPrefixRemainRejected()throws Exception{File base=Files.createTempDirectory("whisper-cancel-").toFile();byte[] v={1};Map<String,SafeModelZip.Expected> expected=Collections.singletonMap("x",new SafeModelZip.Expected(1,SafeModelZip.hex(MessageDigest.getInstance("SHA-256").digest(v))));File z=archive(base,WhisperModelStore.PREFIX+"x",v);try{SafeModelZip.unpack(z,new File(base,"cancel"),expected,()->true,WhisperModelStore.PREFIX);fail("cancel ignored");}catch(InterruptedIOException correct){}try{SafeModelZip.unpack(z,new File(base,"prefix"),expected,()->false,"unbounded/");fail("unknown configured prefix accepted");}catch(IOException correct){} }
 private static Set<String> ids(List<VoiceModels.Entry> entries){Set<String> out=new LinkedHashSet<>();for(VoiceModels.Entry e:entries){assertTrue("duplicate public model: "+e.id,out.add(e.id));assertTrue("unexecutable public model: "+e.id,VoiceModelPolicy.known(e.id));}return out;}
 private static File archive(File dir,String name,byte[] value)throws Exception{File target=new File(dir,UUID.randomUUID()+".zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(target))){z.putNextEntry(new ZipEntry(name));z.write(value);z.closeEntry();}return target;}
}

